    // Forward elimination to form upper-triangular matrix
    let mut i: usize = 0;
    while i < n {
        // Partial pivoting (optional but stable)
        let mut max_row = i;
        let mut j = i + 1;
        while j < n {
            if a[j][i].abs() > a[max_row][i].abs() {
                max_row = j;
            }
            j += 1;
        }
        if max_row != i {
            // Swap rows in a
            let temp_row = a[i].clone();
            a[i] = a[max_row].clone();
            a[max_row] = temp_row;
            // Swap corresponding entries in b
            let temp_b = b[i];
            b[i] = b[max_row];
            b[max_row] = temp_b;
        }

        // Eliminate entries below pivot
        let mut k = i + 1;
        while k < n {
            let factor = a[k][i] / a[i][i];
            // Update the row k
            let mut col: usize = i;
            while col < n {
                a[k][col] -= factor * a[i][col];
                col += 1;
            }
            b[k] -= factor * b[i];
            k += 1;
        }

        i += 1;
    }

    // Back substitution
    let mut x = vec![0.0; n];
    let mut row = n;
